class DocumentUploadSerializer(serializers.ModelSerializer):
    folder_id = serializers.IntegerField(write_only=True)

    class Meta:
        model = UserDocument
        fields = ['title', 'file', 'folder_id']

    def create(self, validated_data):
        folder_id = validated_data.pop('folder_id')
        user = self.context['request'].user
        folder = get_object_or_404(Folder, id=folder_id, owner=user)
        return UserDocument.objects.create(folder=folder, owner=user, **validated_data)
